import { createRoot } from 'react-dom/client';
import { Gauge, LayoutDashboard, Package, Files, ReceiptText, Ship, Wallet, Users, Plus, BellRing, Building2, Calculator, ArrowUpRight, ArrowRight, Download, RefreshCw, LogOut, X, ChevronRight, FileText, Check, AlertCircle, Anchor, Upload, Eye, Trash2, Leaf, LockKeyhole } from 'lucide-react';
